-- Dead triggers (deep audit, 2026-11-15): Legendary enchants whose trigger never fired, because the spell has no proc
-- flags and no spell_proc row (Ascension keeps those rules in its own database). Each now fires from the abilities
-- its tooltip names, through spell_wcme_enchant_action. Rows that list two spells cast both from the build with the
-- multi-cast change (PR #164); older builds cast the first one.
DELETE FROM `spell_proc` WHERE `SpellId` IN (81251, 978219, 990190, 81407, 978742, 953313, 978208, 274471, 954262, 275616, 977921, 977764, 1180221, 81399, 977717, 977817, 277847, 1180481, 272095, 978236, 977824, 978721);
DELETE FROM `spell_script_names` WHERE `spell_id` IN (81251, 978219, 990190, 81407, 978742, 953313, 978208, 274471, 954262, 275616, 977921, 977764, 1180221, 81399, 977717, 977817, 277847, 1180481, 272095, 978236, 977824, 978721);
